function v23Toast(root,flash){const text=flash.textContent.replace('关闭提示','').trim();if(!text){flash.remove();return;}const bad=!!V23.flashErr||/^未完成/.test(text);V23.flashErr=false;const t=document.createElement('div');t.className='v23-toast '+(bad?'err':'ok');t.setAttribute('role',bad?'alert':'status');t.innerHTML=`${v23I(bad?'help':'check')}<span>${e(text)}</span><button type="button" data-fe="clearFlash" aria-label="关闭提示">${v23I('close')}</button>`;flash.remove();(FE.mode==='h5'?root.querySelector('.fe-phone'):root).appendChild(t);FE.flash='';}
function v23DecorateProvider(main,h5){const banner=main.querySelector(':scope > .fe-profile-banner');if(!banner)return;const pid=FE.page==='v22Offer'?getBy('products',FE.id)?.provider:FE.id,p=getBy('providers',pid),m=p&&v22Meta(p.id);
 const hero=document.createElement('section');hero.className='v23-phero';banner.before(hero);hero.innerHTML='<div class="v23-phero-cover"></div>';hero.appendChild(banner);
 if(m){const st=document.createElement('span');st.className='v23-status v23-status-'+v23StatusKey(m.online);st.innerHTML='<i></i>'+e(m.online);banner.querySelector('.fe-avatar')?.appendChild(st);}
 const acts=document.createElement('div');acts.className='v23-phero-actions';
 const follow=main.querySelector('.v22-secondary [data-v22-command="follow"],.v22-secondary [data-v22-command="unfollow"]'),consult=main.querySelector('.v22-profile-actions [data-v22-command="consult"]'),book=main.querySelector('.v22-profile-actions [data-fe="book"]');
 if(follow){const on=follow.dataset.v22Command==='unfollow';follow.className='v23-follow'+(on?' on':'');follow.innerHTML=v23I('heart')+(on?'已关注':'关注');acts.appendChild(follow);}
 if(!h5&&consult){const c=consult.cloneNode(false);c.className='fe-btn v23-btn-soft';c.innerHTML=v23I('chat')+'先咨询';acts.appendChild(c);}
 if(!h5&&book){const b=book.cloneNode(false);b.className='fe-btn primary';b.innerHTML=v23I('calendar')+'选择时间并预约';acts.appendChild(b);}
 const more=[...main.querySelectorAll('.v22-secondary button, .ops16-identity-note button')];
 if(more.length){const d=document.createElement('details');d.className='v23-more';d.innerHTML=`<summary aria-label="更多操作">${v23I('more')}</summary><div class="v23-more-menu"></div>`;for(const b of more){b.className='v23-more-item';d.lastElementChild.appendChild(b);}acts.appendChild(d);}
 banner.appendChild(acts);main.querySelector('.v22-secondary')?.remove();
 const left=main.querySelector(':scope > .fe-side-grid > div');
 const voice=[...main.querySelectorAll(':scope > .v22-panel')].find(x=>x.querySelector('.v22-voice,.v22-profile-bits'));if(voice){voice.classList.add('v23-voice-card');if(left)left.prepend(voice);else hero.after(voice);}
 const notes=[...main.querySelectorAll(':scope > .ops16-note, :scope > .ops16-identity-note')];if(notes.length){const box=document.createElement('section');box.className='v23-safety';box.innerHTML=`${v23I('shield')}<div><b>安全提示</b>${notes.map(n=>`<p>${e((n.matches('p')?n.textContent:n.querySelector('p')?.textContent||'').trim())}</p>`).join('')}</div>`;notes.forEach(n=>n.remove());(left||main).appendChild(box);}
 const aside=main.querySelector(':scope > .fe-side-grid > aside .fe-panel');if(!h5&&aside&&consult){const c=consult.cloneNode(false);c.className='fe-btn v23-btn-soft v23-block';c.innerHTML=v23I('chat')+'先咨询，再决定';aside.querySelector('[data-fe="book"]')?.after(c);}
 const bar=main.querySelector('.v22-profile-actions');if(bar){if(h5){bar.querySelector('[data-v22-command="consult"]')?.insertAdjacentHTML('afterbegin',v23I('chat'));main.appendChild(bar);}else bar.remove();}}
function v23Decorate(){const root=document.getElementById('feRoot');if(!root||FE.mode==='admin')return;const h5=FE.mode==='h5',page=FE.page,isRoot=V23_ROOT.has(page),cat=v23Cat(page);
 root.classList.add('v23');root.classList.toggle('v23-h5',h5);root.classList.toggle('v23-pc',!h5);root.classList.toggle('v23-sub',!isRoot);root.classList.toggle('v23-rootpage',isRoot);root.dataset.cat=cat;
 const phone=root.querySelector('.fe-phone'),main=root.querySelector('#feMain');if(!phone||!main)return;
 const flash=main.querySelector(':scope > .fe-notice[role="status"]');if(flash)v23Toast(root,flash);
 const mask=root.querySelector(':scope > .fe-dialog-mask');if(mask&&h5)phone.appendChild(mask);
 if(h5)for(const x of main.querySelectorAll('.v23-sheet-mask,.v23-sheet'))phone.appendChild(x);
 const help=main.querySelector('.mcn-helpbar [data-mcn-help]')?.dataset.mcnHelp;for(const x of main.querySelectorAll('.mcn-helpbar'))x.remove();if(help)root.querySelector(h5?'.v23-appbar-actions':'.v23-top-actions')?.insertAdjacentHTML('afterbegin',`<button type="button" class="v23-icon-btn v23-help-btn" data-mcn-help="${e(help)}" aria-label="业务 / 字段说明" title="业务 / 字段说明">${v23I('help')}</button>`);
 if(page==='provider'||page==='v22Offer')v23DecorateProvider(main,h5);
 if(h5&&page==='chat')main.querySelector(':scope > .fe-headcopy')?.classList.add('v23-dup');
 if(h5&&!isRoot){const h1=main.querySelector('.fe-headcopy h1');if(h1&&h1.textContent.trim()===v23Title(page))h1.classList.add('v23-dup');for(const b of main.querySelectorAll(':scope > .fe-btn, :scope > .fe-back'))if(/^(←|返回)/.test(b.textContent.trim()))b.classList.add('v23-hide');}
 const foot=main.querySelector(':scope > .fe-footer');
 if(!h5&&cat==='mine'&&feAuthIsSignedIn()&&!FE_AUTH_SCREENS.has(page)){const wrap=document.createElement('div');wrap.className='v23-account';wrap.innerHTML=`<aside class="v23-account-side" aria-label="个人中心导航">${v23SideMenu()}</aside><section class="v23-account-main"></section>`;const col=wrap.lastElementChild;for(const n of [...main.childNodes])if(n!==foot)col.appendChild(n);main.prepend(wrap);}
 if(!h5&&!isRoot&&!FE_AUTH_SCREENS.has(page))main.insertAdjacentHTML('afterbegin',v23Crumbs(page));
 if(foot)foot.outerHTML=v23Footer(h5);
 const map=db.users.filter(u=>(u.v22Demo||u.mcnDemo)&&u.provider!=='已认证'&&/ · /.test(u.name)).map(u=>[u.name,v23Name(u)]);if(map.length){const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(!n.nodeValue.includes(' · '))continue;let v=n.nodeValue;for(const [a,b] of map)if(v.includes(a))v=v.split(a).join(b);if(v!==n.nodeValue)n.nodeValue=v;}}
 if(page==='messages'&&V23.msgTab==='notices')v23MarkSeen();
 v23AudioSync();if(typeof feLocalePaint==='function')feLocalePaint();}
const v23RenderBefore=feRender;
feRender=function(...args){if(FE.mode==='admin')return v23RenderBefore(...args);const old=document.getElementById('feMain'),key=FE.mode+'|'+FE.page+'|'+FE.id,keep=V23.lastKey===key&&old?old.scrollTop:0;if(!FE.history.length)FE.history.push({page:FE.page,id:FE.id});const out=v23RenderBefore(...args);try{v23Decorate();}catch(err){console.error('V23 layout',err);}const main=document.getElementById('feMain');if(main&&FE.mode==='h5')main.scrollTop=keep;V23.lastKey=FE.mode+'|'+FE.page+'|'+FE.id;if(FE.mode!=='admin')document.title='伴屿 · '+v23Title(FE.page)+' · 陪伴服务平台原型';return out;};
document.addEventListener('keydown',ev=>{if(FE.mode==='admin')return;if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){const box=document.querySelector('#feRoot .v23-top-search input');if(box){ev.preventDefault();box.focus();}}});
